head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[input > P > customModelFormatter]<br/>바인딩된 DataCollection 에 확정 입력값이 반영되기 전에 형식을 변환하는 사용자 정의 함수를 설정합니다.",
    "validation" : [
        "확정된 입력값의 형식을 변환하기 위한 사용자 정의 함수를 설정합니다.",
        "사용자 정의 함수의 반환값이 DataCollection 에 저장됩니다.",
        "customModelUnformatter 속성이 설정되지 않으면 사용자 정의 함수의 첫번째 파라미터에는 컴포넌트의 확정 입력값이 전달됩니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.get_text = function(target) {    
    let rtn = '';
    let tagName = target.tagName

    if (tagName !== "INPUT") {
        rtn = target.textContent
        wf_body_bottom.getObj("scwin").setReturnValue("text : " + rtn);    
    }
    else {
        rtn = target.value
        wf_body_bottom.getObj("scwin").setReturnValue("text : " + rtn);   
    }    
}



scwin.fn_modelformatter = function (newVal, oldVal) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====formatter 적용 전=====");        
    // wf_body_bottom.getObj("scwin").setReturnValue("oldValue : " + oldVal);        
    wf_body_bottom.getObj("scwin").setReturnValue("newValue : " + newVal);        

    return newVal + "_CMF ";
}



scwin.btn_getBindData_onclick = function (e) {

};


scwin.target1_onblur = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====formatter 적용 후=====");  
    scwin.get_text(e.target);

    let rtn = ''
    rtn = dm_ref.get("key1");

    wf_body_bottom.getObj("scwin").setReturnValue("바인딩 값 : " + rtn);
};
